<script lang="ts">
 import '../lib/styles.css';import {onMount} from 'svelte';import {page} from '$app/state';import {goto} from '$app/navigation';import {app,refresh,run,usage} from '../lib/app.svelte';import {claimStore} from '../lib/store';import {guard} from '../lib/workflow';import Icon from '../lib/components/Icon.svelte';import {download} from '../lib/exports';
 let {children}=$props();let now=$state(Date.now());let bootError=$state('');
 const actor=$derived(app.data?.users.find(u=>u.id===app.data?.session?.userId));
 const path=$derived(page.url.pathname);
 const redirect=$derived(app.ready&&path!=='/'?guard(path,actor,app.data?.session||null,Math.max(now,Date.now())):null);
 const home=$derived(actor?.role==='Manager'?'/manager':actor?.role==='Finance'?'/finance':'/dashboard');
 const nav=$derived(actor?.role==='Employee'?[['/dashboard','grid','Overview'],['/claims','claim','My claims']]:actor?.role==='Manager'?[['/manager','claim','Approval inbox'],['/dashboard','chart','Dashboard']]:[['/finance','claim','Finance queue'],['/batches','wallet','Payment batches'],['/dashboard','chart','Dashboard'],['/policy','shield','Expense policy'],['/settings','settings','Settings']]);
 const waiting=$derived(app.data?.claims.filter(c=>actor?.role==='Manager'?c.status==='Submitted':actor?.role==='Finance'?c.status==='Manager approved':c.status==='Returned for correction').length||0);
 $effect(()=>{if(app.ready){document.documentElement.dataset.theme=app.data?.theme||'light';if(path==='/')goto(actor?home:'/signin',{replaceState:true});else if(redirect)goto(redirect,{replaceState:true});}});
 onMount(()=>{let alive=true;claimStore.init().then(()=>{if(alive){refresh();app.ready=true;usage();}}).catch(e=>{bootError=e.message;});const interval=setInterval(()=>{now=Date.now();app.warning=!!app.data?.session&&now-app.data.session.activityAt>=14*60000;},5000);const activity=()=>{if(app.ready&&actor&&!app.warning){try{claimStore.touch();refresh();}catch{now=Date.now();}}};document.addEventListener('pointerdown',activity);document.addEventListener('keydown',activity);return()=>{alive=false;clearInterval(interval);document.removeEventListener('pointerdown',activity);document.removeEventListener('keydown',activity);};});
 async function logout(){await run(()=>claimStore.signOut());goto('/signin');}
</script>
<svelte:head><title>ClaimEase — Claim it. Clear it.</title><meta name="description" content="A private, free, single-browser expense claim and reimbursement demo. Claim it. Clear it."/></svelte:head>
<a href="#main" class="skip-link">Skip to content</a>
{#if bootError}<main class="recovery" id="main"><div class="brand"><img src="/favicon.svg" alt=""/>ClaimEase</div><h1>Let’s protect your data.</h1><p role="alert">{bootError}</p>{#if claimStore.rawRecovery()}<button class="primary" onclick={()=>download(claimStore.rawRecovery(),'claimease-recovery.json','application/json')}>Download original recovery data</button>{/if}<button onclick={()=>location.reload()}>Try again</button><p>No existing browser data has been overwritten. Do not clear storage before saving a recovery copy.</p></main>
{:else if !app.ready}<main id="main" class="loading"><div class="brand"><img src="/favicon.svg" alt=""/>ClaimEase</div><p>Preparing your private workspace…</p><div class="skeleton"></div><div class="skeleton"></div></main>
{:else if path==='/signin'}{@render children()}
{:else if actor&&!redirect}
 <div class="app-shell"><aside class="sidebar"><a class="brand" href={home}><img src="/favicon.svg" alt=""/>ClaimEase<span class="wordmark-dot"></span></a><div class="company"><span class="company-monogram">K</span><div><strong>Kestrel Labs</strong><small>Expense workspace</small></div><span class="fictional-label">DEMO</span></div><p class="nav-section">WORKSPACE</p><nav aria-label="Main navigation">{#each nav as [url,icon,label]}<a href={url} class:active={path===url}><Icon name={icon}/>{label}{#if (url==='/manager'||url==='/finance')&&waiting}<span class="count">{waiting}</span>{/if}</a>{/each}</nav><div class="sidebar-bottom"><a href="/privacy" class:active={path==='/privacy'}><Icon name="shield"/>Privacy & backup</a><a href="/about" class:active={path==='/about'}><Icon name="info"/>About ClaimEase</a><div class="storage"><div><Icon name="lock" size={14}/><strong>Stored on this device</strong></div><meter min="0" max="5242880" value={app.usage.metadata} aria-label="Metadata storage used"></meter><small>{((app.usage.metadata+app.usage.receipts)/1048576).toFixed(1)} MB locally · {Math.round(app.usage.metadata/5242880*100)}% metadata</small></div></div></aside>
 <div class="workspace"><header class="topbar"><div class="breadcrumb">Workspace <span>/</span> <strong>{nav.find(n=>n[0]===path)?.[2]|| (path.startsWith('/claims/')?'Claim details':path==='/privacy'?'Privacy & backup':path==='/notifications'?'Notifications':'About')}</strong></div><div class="top-actions"><span class="demo-badge"><span></span>Demo mode: data is stored only in this browser</span><button class="icon-button" aria-label={app.data?.theme==='dark'?'Use light theme':'Use dark theme'} onclick={()=>run(()=>claimStore.setTheme(app.data?.theme==='dark'?'light':'dark'))}><Icon name={app.data?.theme==='dark'?'sun':'moon'}/></button><a class="icon-button notification-button" href="/notifications" aria-label={`Notifications, ${waiting} waiting`}><Icon name="bell"/>{#if waiting}<span class="notification-dot"></span>{/if}</a><div class="user-avatar">{actor.name.split(' ').map(n=>n[0]).join('')}</div><div class="user-label"><strong>{actor.name}</strong><small>{actor.role}</small></div><button class="icon-button" onclick={logout} aria-label="Sign out" title="Sign out"><Icon name="logout"/></button></div></header>
 <div class="mobile-demo">Demo mode: data is stored only in this browser</div>
 {#if app.warning}<div class="session-warning" role="alert">You’ll be signed out after 15 minutes of inactivity.<button onclick={()=>run(()=>{claimStore.touch();app.warning=false;})}>Stay signed in</button></div>{/if}
 {#if app.usage.metadata>4194304||(app.usage.quota&&app.usage.usage/app.usage.quota>.85)}<div class="session-warning" role="alert">Browser storage is nearly full. Export a backup before adding more receipts.</div>{/if}
 <main id="main" class="main-content">{@render children()}</main><footer class="workspace-footer"><span>Claim it. Clear it.</span><span>Private by design. Local by default.</span></footer></div>
 <nav class="bottom-nav" aria-label="Mobile navigation"><a class:active={path===home} href={home}><Icon name="grid"/>Home</a><a class:active={path===(actor.role==='Employee'?'/claims':actor.role==='Manager'?'/dashboard':'/batches')} href={actor.role==='Employee'?'/claims':actor.role==='Manager'?'/dashboard':'/batches'}><Icon name={actor.role==='Finance'?'wallet':'claim'}/>{actor.role==='Employee'?'Claims':actor.role==='Manager'?'Reports':'Batches'}</a>{#if actor.role==='Finance'}<a href="/policy"><Icon name="shield"/>Policy</a>{/if}<a href="/privacy"><Icon name="lock"/>Backup</a><a href={actor.role==='Finance'?'/settings':'/about'}><Icon name="settings"/>More</a></nav></div>
{/if}
{#if app.toast}<div class="toast" role="status"><Icon name="info"/><span>{app.toast}</span><button aria-label="Dismiss message" onclick={()=>app.toast=''}><Icon name="close" size={16}/></button></div>{/if}